internal/cli/help.go:115:		long:    "Previews the same repository-specific workflow setup would install, without writing files. Inherits the saved guidance mode; --strict and --normal override this preview only. Save a mode with `setup --strict` or `setup --normal`. Outside a repository, prints standalone Graph guidance (normal unless --strict is supplied).",
internal/cli/help.go:520:			"--assert is the preflight: it parses a command line against this binary and exits non-zero if this binary would reject it, WITHOUT running anything — no repo read, no index build, no writes. Run it once before a batch or a benchmark cell so a flag set built for a different build fails at startup instead of failing the first call of every session and leaving an agent to explore by hand. Repeatable. It runs each command's real parser, so a command that requires a flag will say so; assert the command line you actually intend to run.",
		return exactSearchStore{}, nil, err
	}
	store := searchStoreEntryFor(entry)
	path := filepath.Join(store.root, store.relative)
	if _, err := os.Stat(path); err != nil {
		return exactSearchStore{}, nil, ErrSearchStoreMissing
	}
	digest, err := entry.digest()
	if err != nil {
		return exactSearchStore{}, nil, ErrSearchStoreMissing
	}

	db, err := sql.Open("sqlite", "file:"+sqliteURLPath(path)+"?immutable=1&mode=ro")
	if err != nil {
		return exactSearchStore{}, nil, err
	}
	fail := func(err error) (exactSearchStore, *sql.DB, error) {
		_ = db.Close()
		return exactSearchStore{}, nil, err
	}
	var version, storedDigest string
	if err := readSearchStoreMetaKey(ctx, db, "store_version", &version); err != nil {
		return fail(err)
	}
	if err := readSearchStoreMetaKey(ctx, db, "entry_digest", &storedDigest); err != nil {
		return fail(err)
	}
	if version != searchStoreVersion || storedDigest != digest.String() {
		return fail(ErrSearchStoreMissing)
	}
	var meta searchStoreMeta
	if err := readSearchStoreMetaKey(ctx, db, "envelope", &meta); err != nil {
		return fail(err)
	}
	if meta.Tree != tree {
		return fail(searchStoreTreeMismatch(tree, meta.Tree))
	}
	return exactSearchStore{path: path, entryDigest: storedDigest, meta: meta}, db, nil
}

